<?php
namespace Tests\Feature;
use App\Models\ContractTemplate; use App\Models\ContractTemplateVersion; use App\Models\ContractType; use App\Models\Customer; use App\Models\Language; use App\Models\Role; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Laravel\Sanctum\Sanctum; use Tests\TestCase;
class VersionedContractGenerationTest extends TestCase { use RefreshDatabase; protected function setUp(): void { parent::setUp(); $u=User::factory()->create();$u->roles()->attach(Role::firstOrCreate(['name'=>'super_admin']));Sanctum::actingAs($u,['access']); }
 public function test_contract_uses_the_selected_active_language_version_and_keeps_snapshot(): void { $type=ContractType::where('slug','customer')->firstOrFail();$template=ContractTemplate::create(['name'=>'Agreement','contract_type_id'=>$type->id,'cover_text'=>'','content'=>'<p>old</p>']);$english=Language::create(['name'=>'English','code'=>'en']);$persian=Language::create(['name'=>'Persian','code'=>'fa']);$englishVersion=ContractTemplateVersion::create(['contract_template_id'=>$template->id,'language_id'=>$english->id,'version_number'=>1,'content'=>'<p>{{customer.name}} English</p>','status'=>'active','is_current'=>true]);$persianVersion=ContractTemplateVersion::create(['contract_template_id'=>$template->id,'language_id'=>$persian->id,'version_number'=>1,'content'=>'<p>{{customer.name}} Persian</p>','status'=>'active','is_current'=>true]);$customer=Customer::factory()->create();$this->postJson('/api/contracts',['template_id'=>$template->id,'customer_id'=>$customer->id,'language_id'=>$persian->id,'status'=>'active','start_date'=>'2026-09-17'])->assertCreated()->assertJsonPath('data.contract_template_version_id',$persianVersion->id)->assertJsonPath('data.content',"<p>{$customer->name} Persian</p>");$this->postJson('/api/contracts',['template_id'=>$template->id,'customer_id'=>$customer->id,'status'=>'active','start_date'=>'2026-09-17'])->assertUnprocessable();$this->assertDatabaseHas('contract_template_versions',['id'=>$englishVersion->id,'is_current'=>true]); } }
